    {
      "id": 1,
      "claim": "The 'largest mountain on Earth' is either Mount Everest (highest above sea level) or Mauna Kea (tallest from base to peak).",
      "evidence": "Standard geographical definitions identify Everest as the highest summit (8,848 m) and Mauna Kea as the tallest from base (~10,210 m).",
      "weight": 0.1,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The Very Large Telescope (VLT) is located at Paranal Observatory in Chile, at an altitude of approximately 2.6 km.",
      "evidence": "ESO site specifications place the VLT in the Atacama Desert, Chile, at ~24°S latitude and 2,635 m elevation.",
      "weight": 0.1,
      "depends_on": []
    },
    {
      "id": 3,
      "claim": "The great-circle distance from the VLT to both Mount Everest and Mauna Kea exceeds 10,000 km.",
      "evidence": "Geographic coordinates show Paranal is ~15,000 km from Everest and ~12,000 km from Mauna Kea.",
      "weight": 0.2,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "The maximum line-of-sight distance from the VLT to a terrestrial target is limited by Earth's curvature to approximately 500-600 km.",
      "evidence": "Using the horizon formula d ≈ √(2Rh_obs) + √(2Rh_target), with R=6371 km, h_obs=2.6 km, and h_target up to 10 km, the limit is ~180 km + ~350 km ≈ 530 km.",
      "weight": 0.3,
      "depends_on": [2]
    },
    {
      "id": 5,
      "claim": "The distance to the mountains (Step 3) far exceeds the geometric line-of-sight limit (Step 4), making direct optical observation impossible.",
      "evidence": "10,000+ km > 530 km; the curvature of the Earth blocks the line of sight.",
      "weight": 0.2,
      "depends_on": [3, 4]
    },
    {
      "id": 6,
      "claim": "Even if line-of-sight existed, the VLT is optically and mechanically designed for astronomical distances (infinity) and cannot focus on or track terrestrial targets at finite, close ranges.",
      "evidence": "Astronomical telescopes have fixed focal lengths optimized for infinite conjugates; focusing on a target 100 km away would require significant optical reconfiguration not present in the VLT design.",
      "weight": 0.1,
      "depends_on": [2]
    }
  ],
